import { useCallback, useEffect, useState } from 'react';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import type { LoanTypeDto } from '@/features/selfServices/types/loanType.types';

export function useActiveLoanTypes() {
    const [types, setTypes] = useState<LoanTypeDto[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    const reload = useCallback(async () => {
        setLoading(true);
        setError(null);
        try {
            const res = await apiGet({
                endpoint: endpoints.loanType.list,
                queryParams: { active_only: 1 },
            });
            setTypes((res.data?.data ?? []) as LoanTypeDto[]);
        } catch {
            setError('تعذر تحميل أنواع القروض');
            setTypes([]);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        reload();
    }, [reload]);

    const options = types.map((t) => ({ name: t.name, value: t.code }));

    return { types, options, loading, error, reload };
}
