import { Form } from '@/components/ui/form';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { useState } from 'react';
import { useActiveLoanTypes } from '@/features/selfServices/hooks/useActiveLoanTypes';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { toast } from 'sonner';
import SelectInputForm from '@/components/forms/SelectInputForm';
import { DateInputForm } from '@/components/forms/DateInputForm';
import Cookies from 'js-cookie';
import { format } from 'date-fns';
import { AddLoanRequestFormValues, AddLoanRequestSchema } from '../schemas/insurances/add-loan-request-schema';
import TextInputForm from '@/components/forms/TextInputForm';
import MultipleReasonsInput from '@/components/forms/MultipleReasonsInput';

interface Props {
    setShowPopup: (value: boolean) => void;
    handleRefreshTable: () => void;
}

export default function LoanRequestForm({ setShowPopup, handleRefreshTable }: Props) {
    const { options: loanTypeOptions, types: loanTypes, loading: loanTypesLoading } = useActiveLoanTypes();
    const [error, setError] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [reasonInput, setReasonInput] = useState('');
    const [reasons, setReasons] = useState<string[]>([]);
    const employee_id = JSON.parse(Cookies.get('user') || '{}').id;

    const form = useForm<AddLoanRequestFormValues>({
        resolver: zodResolver(AddLoanRequestSchema),
    });

    const selectedTypeCode = form.watch('loan_type');
    const selectedTypeMeta = loanTypes.find((t) => t.code === selectedTypeCode);

    const addReason = () => {
        const value = reasonInput.trim();
        if (!value) return;
        setReasons((prev) => [...prev, value]);
        setReasonInput('');
    };

    const removeReason = (indexToRemove: number) => {
        setReasons((prev) => prev.filter((_, index) => index !== indexToRemove));
    };

    const onSubmit = async (data: AddLoanRequestFormValues) => {
        setLoading(true);
        setError(null); // Clear previous errors

        const normalizedReasons = reasons.map((r) => r.trim()).filter(Boolean);
        const pending = reasonInput.trim();
        const allReasonParts = pending ? [...normalizedReasons, pending] : normalizedReasons;
        if (allReasonParts.length === 0) {
            setError('يرجى إدخال سبب الطلب');
            setLoading(false);
            return;
        }
        const reason = allReasonParts.join('، ');

        const { date, ...rest } = data;
        const formatedData = {
            ...rest,
            employee_id,
            amount: Number(rest.amount),
            installments: Number(rest.installments),
            data: format(date, 'yyyy-MM-dd'),
            reason,
        };
        try {
            await apiPost({
                endpoint: endpoints.loan.create,
                body: formatedData,
                config: { headers: { 'Content-Type': 'multipart/form-data' } },
            });

            toast('تم اضافة الطلب بنجاح');
            handleRefreshTable();
            setShowPopup(false);
        } catch (error: any) {
            if (error.response?.data?.errors) {
                // Handle field-specific errors
                Object.entries(error.response.data.errors).forEach(([field, messages]) => {
                    form.setError(field as any, {
                        type: 'manual',
                        message: (messages as string[]).join(', '),
                    });
                });
            } else {
                // Handle generic error
                let errorMessage = 'حدث خطأ أثناء إرسال البيانات. يرجى المحاولة مرة أخرى.';
                if (error.response) {
                    errorMessage = error.response.data.msg || errorMessage;
                } else if (error.request) {
                    errorMessage = 'تعذر الاتصال بالخادم. يرجى التحقق من اتصالك بالإنترنت.';
                }
                setError(errorMessage);
            }
        } finally {
            setLoading(false);
        }
    };

    return (
        <>
            <Form {...form}>
                <form onSubmit={form.handleSubmit(onSubmit)} className="mt-6">
                    {!loanTypesLoading && loanTypeOptions.length === 0 && (
                        <div className="mb-4 p-4 bg-amber-50 border border-amber-200 text-amber-900 rounded-lg text-sm">
                            لا توجد أنواع قروض مفعّلة حالياً. يُرجى مراجعة الموارد البشرية.
                        </div>
                    )}
                    {error && (
                        <div className="mb-4 p-4 bg-red-100 border border-red-400 text-red-700 rounded-lg">
                            <div className="flex justify-between items-center">
                                <span className="">{error}</span>
                                <button onClick={() => setError(null)} className="text-red-700 hover:text-red-900">
                                    ×
                                </button>
                            </div>
                        </div>
                    )}
                    <div className="grid grid-cols-2 gap-3">
                        <SelectInputForm
                            name="loan_type"
                            label="نوع القرض"
                            options={loanTypeOptions}
                            placeholder="اختر نوع القرض"
                        />
                        {selectedTypeMeta && (
                            <p className="col-span-2 text-xs text-primery-blue-800 leading-relaxed">
                                الحد الأقصى للمبلغ:{' '}
                                {Number(selectedTypeMeta.max_amount).toLocaleString('ar-SA', { maximumFractionDigits: 2 })}{' '}
                                ريال — أقصى مدة سداد: {selectedTypeMeta.max_duration_months} شهر — معدل العائد:{' '}
                                {selectedTypeMeta.interest_rate}%
                            </p>
                        )}
                        <TextInputForm name="amount" label="القيمة" placeholder="100" type="number" />
                        <DateInputForm name="date" label="التاريخ" placeholder="2004/04/30" />
                        <TextInputForm name="installments" label="فترة السداد (بالأشهر)" placeholder="12" type="number" />
                        <div className="col-span-2">
                            <MultipleReasonsInput
                                label="السبب"
                                placeholder="اكتب السبب"
                                value={reasonInput}
                                onValueChange={setReasonInput}
                                reasons={reasons}
                                onAddReason={addReason}
                                onRemoveReason={removeReason}
                            />
                        </div>
                    </div>
                    <div className="flex flex-row gap-4 mt-12">
                        <SecondaryButton
                            onClick={() => setShowPopup(false)}
                            type="button"
                            className="w-full text-base leading-5 tracking-normal py-[10px] font-medium"
                        >
                            إلغاء
                        </SecondaryButton>
                        <PrimaryButton
                            type="submit"
                            className="w-full text-base leading-5 tracking-normal font-medium py-[10px]"
                        >
                            {loading ? 'جاري الحفظ...' : 'تقديم الطلب'}
                        </PrimaryButton>
                    </div>
                </form>
            </Form>
        </>
    );
}
